14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    let mut current_cmd = &*cmd;
36	    if cmd.is_multicall_set() {
37	        // A multicall executable dispatches on the file name of argv0 (the
38	        // "applet"), matching clap's own parser behavior. When argv0 is the
39	        // multicall launcher itself (e.g. `busybox`, itself a registered
40	        // subcommand) the following argument selects the applet; an
41	        // unrecognized invocation name yields no candidates rather than
42	        // falling back to the root command.
43	        let applet = raw_args
44	            .next_os(&mut cursor)
45	            .and_then(|argv0| std::path::Path::new(argv0).file_stem().map(OsStr::to_owned));
46	        if let Some(applet) = applet.as_deref().and_then(OsStr::to_str) {
47	            if let Some(subcmd) = cmd.find_subcommand(applet) {
48	                debug!("complete: multicall applet={applet:?}");
49	                current_cmd = subcmd;
50	            } else {
51	                debug!("complete: unrecognized multicall applet={applet:?}");
52	                return Ok(Vec::new());
53	            }
54	        } else {
55	            debug!("complete: multicall without an applet name");
56	            return Ok(Vec::new());
57	        }
58	    } else if !cmd.is_no_binary_name_set() {
59	        raw_args.next_os(&mut cursor);
60	    }
61	    let mut pos_index = 1;
62	    let mut is_escaped = false;
63	    let mut next_state = ParseState::ValueDone;
64	    // Options that already took their values on this command line, used to
65	    // reject a repeated occurrence of a non-repeatable option.
66	    let mut seen_options = std::collections::HashSet::<String>::new();
67	    while let Some(arg) = raw_args.next(&mut cursor) {
68	        let current_state = next_state;
69	        next_state = ParseState::ValueDone;
70	        debug!(
71	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
72	            arg.to_value_os(),
73	        );
74	        if cursor == target_cursor {
75	            return complete_arg(
76	                &arg,
77	                current_cmd,
78	                current_dir,
79	                pos_index,
80	                is_escaped,
81	                current_state,
82	                &seen_options,
83	            );
84	        }
85	
86	        if let Ok(value) = arg.to_value() {
87	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
88	                current_cmd = next_cmd;
89	                pos_index = 1;
90	                seen_options.clear();
91	                continue;
92	            }
93	        }
94	
95	        // An option whose value is required cannot be followed by another
96	        // option or the escape token; the missing value makes the whole
97	        // command line invalid, so nothing can be completed. An option whose
98	        // value is optional instead drops its pending state and the token is
99	        // processed on its own.
100	        if !is_escaped && looks_like_option(&arg) {
101	            if let ParseState::Opt((opt, count)) = &current_state {
102	                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
103	                if *count <= min && min > 0 && !opt.is_allow_hyphen_values_set() {
104	                    debug!(
105	                        "complete: missing required value for opt={:?}",
106	                        opt.get_id()
107	                    );
108	                    return Ok(Vec::new());
109	                }
110	            }
111	        }
112	
113	        if is_escaped {
114	            let positional = current_cmd
115	                .get_positionals()
116	                .find(|p| p.get_index() == Some(pos_index));
117	            if let Some(positional) = positional {
118	                if !is_valid_value(positional, arg.to_value_os()) {
119	                    debug!(
120	                        "complete: invalid value={:?} for positional={:?}",
121	                        arg.to_value_os(),
122	                        positional.get_id()
123	                    );
124	                    return Ok(Vec::new());
125	                }
126	            }
127	            (next_state, pos_index) =
128	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
129	        } else if arg.is_escape() {
130	            is_escaped = true;
131	        } else if opt_allows_hyphen(&current_state, &arg) {
132	            match current_state {
133	                ParseState::Opt((opt, count)) => {
134	                    if !is_valid_value(opt, arg.to_value_os()) {
135	                        debug!(
136	                            "complete: invalid value={:?} for opt={:?}",
137	                            arg.to_value_os(),
138	                            opt.get_id()
139	                        );
140	                        return Ok(Vec::new());
141	                    }
142	                    next_state = parse_opt_value(opt, count);
143	                }
144	                _ => unreachable!("else branch is only reachable in Opt state"),
145	            }
146	        } else if let Some((flag, value)) = arg.to_long() {
147	            if let Ok(flag) = flag {
148	                let opt = current_cmd.get_arguments().find(|a| {
149	                    let longs = a.get_long_and_visible_aliases();
150	                    let is_find = longs.map(|v| {
151	                        let mut iter = v.into_iter();
152	                        let s = iter.find(|s| *s == flag);
153	                        s.is_some()
154	                    });
155	                    is_find.unwrap_or(false)
156	                });
157	
158	                if let Some(opt) = opt {
159	                    let takes_values = opt.get_num_args().expect("built").takes_values();
160	                    if takes_values {
161	                        if !can_repeat(opt) && !seen_options.insert(opt.get_id().to_string()) {
162	                            debug!("complete: repeated non-repeatable opt={flag:?}");
163	                            return Ok(Vec::new());
164	                        }
165	                        if let Some(value) = value {
166	                            if !is_valid_value(opt, value) {
167	                                debug!("complete: invalid value={value:?} for opt={flag:?}");
168	                                return Ok(Vec::new());
169	                            }
170	                        }
171	                    }
172	                    if takes_values && value.is_none() {
173	                        next_state = ParseState::Opt((opt, 1));
174	                    };
175	                } else if pos_allows_hyphen(current_cmd, pos_index) {
176	                    let positional = current_cmd
177	                        .get_positionals()
178	                        .find(|p| p.get_index() == Some(pos_index));
179	                    if let Some(positional) = positional {
180	                        if !is_valid_value(positional, arg.to_value_os()) {
181	                            debug!(
182	                                "complete: invalid value={:?} for positional={:?}",
183	                                arg.to_value_os(),
184	                                positional.get_id()
185	                            );
186	                            return Ok(Vec::new());
187	                        }
188	                    }
189	                    (next_state, pos_index) =
190	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
191	                } else {
192	                    debug!("complete: unknown flag={flag:?}");
193	                    return Ok(Vec::new());
194	                }
195	            }
196	        } else if let Some(short) = arg.to_short() {
197	            let (_, takes_value_opt, mut short) = parse_shortflags(current_cmd, short);
198	            if let Some(opt) = takes_value_opt {
199	                if !can_repeat(opt) && !seen_options.insert(opt.get_id().to_string()) {
200	                    debug!("complete: repeated non-repeatable opt={:?}", opt.get_id());
201	                    return Ok(Vec::new());
202	                }
203	                // Consume an optional `=`, matching how inline short values are
204	                // split elsewhere, so `-F=json` validates `json` rather than
205	                // `=json`.
206	                let mut peek_short = short.clone();
207	                if let Some(Ok('=')) = peek_short.next_flag() {
208	                    short.next_flag();
209	                }
210	                if let Some(value) = short.next_value_os() {
211	                    if !is_valid_value(opt, value) {
212	                        debug!(
213	                            "complete: invalid value={value:?} for opt={:?}",
214	                            opt.get_id()
215	                        );
216	                        return Ok(Vec::new());
217	                    }
218	                } else {
219	                    next_state = ParseState::Opt((opt, 1));
220	                }
221	            } else if pos_allows_hyphen(current_cmd, pos_index) {
222	                let positional = current_cmd
223	                    .get_positionals()
224	                    .find(|p| p.get_index() == Some(pos_index));
225	                if let Some(positional) = positional {
226	                    if !is_valid_value(positional, arg.to_value_os()) {
227	                        debug!(
228	                            "complete: invalid value={:?} for positional={:?}",
229	                            arg.to_value_os(),
230	                            positional.get_id()
231	                        );
232	                        return Ok(Vec::new());
233	                    }
234	                }
235	                (next_state, pos_index) =
236	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
237	            }
238	        } else {
239	            match current_state {
240	                ParseState::ValueDone | ParseState::Pos(..) => {
241	                    let positional = current_cmd
242	                        .get_positionals()
243	                        .find(|p| p.get_index() == Some(pos_index));
244	                    let Some(positional) = positional else {
245	                        debug!("complete: unrecognized argument={:?}", arg.to_value_os());
246	                        return Ok(Vec::new());
247	                    };
248	                    if !is_valid_value(positional, arg.to_value_os()) {
249	                        debug!(
250	                            "complete: invalid value={:?} for positional={:?}",
251	                            arg.to_value_os(),
252	                            positional.get_id()
253	                        );
254	                        return Ok(Vec::new());
255	                    }
256	                    (next_state, pos_index) =
257	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
258	                }
259	                ParseState::Opt((opt, count)) => {
260	                    if !is_valid_value(opt, arg.to_value_os()) {
261	                        debug!(
262	                            "complete: invalid value={:?} for opt={:?}",
263	                            arg.to_value_os(),
264	                            opt.get_id()
265	                        );
266	                        return Ok(Vec::new());
267	                    }
268	                    next_state = parse_opt_value(opt, count);
269	                }
270	            }
271	        }
272	    }
273	
274	    Err(std::io::Error::other("no completion generated"))
275	}
