277	#[derive(Debug, PartialEq, Eq, Clone)]
278	enum ParseState<'a> {
279	    /// Parsing a value done, there is no state to record.
280	    ValueDone,
281	
282	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
283	    Pos((usize, usize)),
284	
285	    /// Parsing a optional flag argument
286	    Opt((&'a clap::Arg, usize)),
287	}
288	
289	fn complete_arg(
290	    arg: &clap_lex::ParsedArg<'_>,
291	    cmd: &clap::Command,
292	    current_dir: Option<&std::path::Path>,
293	    pos_index: usize,
294	    is_escaped: bool,
295	    state: ParseState<'_>,
296	    seen_options: &std::collections::HashSet<String>,
297	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
298	    debug!(
299	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
300	        arg,
301	        cmd.get_name(),
302	        current_dir,
303	        pos_index,
304	        state
305	    );
306	
307	    // A token under the cursor may itself repeat an option that already took a
308	    // value; for a non-repeatable option this is invalid and yields nothing.
309	    if !is_escaped && matches!(state, ParseState::ValueDone | ParseState::Pos(..)) {
310	        if let Some(opt) = cursor_option(cmd, arg) {
311	            if opt.get_num_args().expect("built").takes_values()
312	                && !can_repeat(opt)
313	                && seen_options.contains(&opt.get_id().to_string())
314	            {
315	                debug!(
316	                    "complete: repeated non-repeatable opt={:?} at cursor",
317	                    opt.get_id()
318	                );
319	                return Ok(Vec::new());
320	            }
321	        }
322	    }
323	
324	    let mut completions = Vec::<CompletionCandidate>::new();
325	
326	    match state {
327	        ParseState::ValueDone => {
328	            // After `--`, subcommands are no longer recognized; every token is
329	            // parsed as a positional value.
330	            if !is_escaped {
331	                if let Ok(value) = arg.to_value() {
332	                    completions.extend(complete_subcommand(value, cmd));
333	                }
334	            }
335	
336	            if let Some(positional) = cmd
337	                .get_positionals()
338	                .find(|p| p.get_index() == Some(pos_index))
339	            {
340	                completions.extend(complete_arg_value(
341	                    arg.to_value(),
342	                    positional,
343	                    current_dir,
344	                    0,
345	                ));
346	            }
347	            if !is_escaped {
348	                completions.extend(complete_option(arg, cmd, current_dir));
349	            }
350	        }
351	        ParseState::Pos((_, num_arg)) => {
352	            if let Some(positional) = cmd
353	                .get_positionals()
354	                .find(|p| p.get_index() == Some(pos_index))
355	            {
356	                completions.extend(complete_arg_value(
357	                    arg.to_value(),
358	                    positional,
359	                    current_dir,
360	                    num_arg.saturating_sub(1),
361	                ));
362	                if !is_escaped
363	                    && positional
364	                        .get_num_args()
365	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
366	                {
367	                    completions.extend(complete_option(arg, cmd, current_dir));
368	                }
369	            }
370	        }
371	        ParseState::Opt((opt, count)) => {
372	            completions.extend(complete_arg_value(
373	                arg.to_value(),
374	                opt,
375	                current_dir,
376	                count.saturating_sub(1),
377	            ));
378	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
379	            // An option whose value is optional (a minimum of zero values)
380	            // always serves its own value at the first value slot; falling back
381	            // to flags and positionals here would let `--color <TAB>` mix
382	            // color values with unrelated candidates. Options that require at
383	            // least one value keep offering the alternatives once their
384	            // required values have been supplied.
385	            if count > min && min > 0 {
386	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
387	                completions.extend(complete_arg(
388	                    arg,
389	                    cmd,
390	                    current_dir,
391	                    pos_index,
392	                    is_escaped,
393	                    ParseState::ValueDone,
394	                    seen_options,
395	                )?);
396	            }
397	        }
398	    }
399	    if completions.iter().any(|a| !a.is_hide_set()) {
400	        completions.retain(|a| !a.is_hide_set());
401	    }
402	    let mut seen_ids = std::collections::HashSet::new();
403	    let mut seen_values = std::collections::HashSet::new();
404	    completions.retain(move |a| {
405	        if let Some(id) = a.get_id().cloned() {
406	            seen_ids.insert(id)
407	        } else {
408	            // Candidates without an id are deduplicated by value, keeping the
409	            // first occurrence
410	            seen_values.insert(a.get_value().to_owned())
411	        }
412	    });
413	
414	    let mut tags = Vec::new();
415	    for candidate in &completions {
416	        let tag = candidate.get_tag().cloned();
417	        if !tags.contains(&tag) {
418	            tags.push(tag);
419	        }
420	    }
421	    completions.sort_by_key(|c| {
422	        (
423	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
424	            c.get_display_order(),
425	        )
426	    });
427	
428	    Ok(completions)
429	}
