431	fn complete_option(
432	    arg: &clap_lex::ParsedArg<'_>,
433	    cmd: &clap::Command,
434	    current_dir: Option<&std::path::Path>,
435	) -> Vec<CompletionCandidate> {
436	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
437	    let mut completions = Vec::<CompletionCandidate>::new();
438	    if arg.is_empty() {
439	        completions.extend(longs_and_visible_aliases(cmd));
440	        completions.extend(hidden_longs_aliases(cmd));
441	
442	        let dash_or_arg = if arg.is_empty() {
443	            "-".into()
444	        } else {
445	            arg.to_value_os().to_string_lossy()
446	        };
447	        completions.extend(
448	            shorts_and_visible_aliases(cmd)
449	                .into_iter()
450	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
451	        );
452	    } else if arg.is_stdio() {
453	        // HACK: Assuming knowledge of is_stdio
454	        let dash_or_arg = if arg.is_empty() {
455	            "-".into()
456	        } else {
457	            arg.to_value_os().to_string_lossy()
458	        };
459	        completions.extend(
460	            shorts_and_visible_aliases(cmd)
461	                .into_iter()
462	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
463	        );
464	
465	        completions.extend(longs_and_visible_aliases(cmd));
466	        completions.extend(hidden_longs_aliases(cmd));
467	    } else if arg.is_escape() {
468	        // HACK: Assuming knowledge of is_escape
469	        completions.extend(longs_and_visible_aliases(cmd));
470	        completions.extend(hidden_longs_aliases(cmd));
471	    } else if let Some((flag, value)) = arg.to_long() {
472	        if let Ok(flag) = flag {
473	            if let Some(value) = value {
474	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
475	                    completions.extend(
476	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
477	                            .into_iter()
478	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
479	                    );
480	                }
481	            } else {
482	                completions.extend(
483	                    longs_and_visible_aliases(cmd)
484	                        .into_iter()
485	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
486	                );
487	                completions.extend(
488	                    hidden_longs_aliases(cmd)
489	                        .into_iter()
490	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
491	                );
492	            }
493	        }
494	    } else if let Some(short) = arg.to_short() {
495	        if !short.is_negative_number() {
496	            // Find the first takes_values option.
497	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
498	
499	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
500	            if let Some(opt) = takes_value_opt {
501	                let mut peek_short = short.clone();
502	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
503	                    short.next_flag();
504	                    true
505	                } else {
506	                    false
507	                };
508	
509	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
510	                completions.extend(
511	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
512	                        .into_iter()
513	                        .map(|comp| {
514	                            let sep = if has_equal { "=" } else { "" };
515	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
516	                        }),
517	                );
518	            } else {
519	                completions.extend(
520	                    shorts_and_visible_aliases(cmd)
521	                        .into_iter()
522	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
523	                );
524	            }
525	        }
526	    }
527	    debug!("complete_option: completions={completions:?}");
528	    completions
529	}
