531	fn complete_arg_value(
532	    value: Result<&str, &OsStr>,
533	    arg: &clap::Arg,
534	    current_dir: Option<&std::path::Path>,
535	    arg_index: usize,
536	) -> Vec<CompletionCandidate> {
537	    let mut values = Vec::new();
538	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
539	
540	    let (prefix, value) =
541	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
542	
543	    let value_os = match value {
544	        Ok(value) => OsStr::new(value),
545	        Err(value_os) => value_os,
546	    };
547	
548	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
549	        values.extend(completer.complete_at(arg_index, value_os));
550	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
551	        values.extend(complete_value_candidates(
552	            value_os,
553	            completer.value_candidates(),
554	        ));
555	    } else if let Some(possible_values) = possible_values(arg) {
556	        if let Ok(value) = value {
557	            values.extend(complete_candidates_str(
558	                value,
559	                possible_value_candidates(possible_values),
560	            ));
561	        }
562	    } else {
563	        match arg.get_value_hint() {
564	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
565	                // Should not complete
566	            }
567	            clap::ValueHint::AnyPath => {
568	                values.extend(complete_path(value_os, current_dir, &|_| true));
569	            }
570	            clap::ValueHint::FilePath => {
571	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
572	            }
573	            clap::ValueHint::DirPath => {
574	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
575	            }
576	            clap::ValueHint::ExecutablePath => {
577	                use is_executable::IsExecutable;
578	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
579	            }
580	            clap::ValueHint::CommandName
581	            | clap::ValueHint::CommandString
582	            | clap::ValueHint::CommandWithArguments
583	            | clap::ValueHint::Username
584	            | clap::ValueHint::Hostname
585	            | clap::ValueHint::Url
586	            | clap::ValueHint::EmailAddress => {
587	                // No completion implementation
588	            }
589	            _ => {
590	                // Safe-ish fallback
591	                values.extend(complete_path(value_os, current_dir, &|_| true));
592	            }
593	        }
594	
595	        values.sort();
596	    }
597	
598	    if let Some(prefix) = prefix {
599	        values = values
600	            .into_iter()
601	            .map(|comp| comp.add_prefix(prefix))
602	            .collect();
603	    }
604	    values = values
605	        .into_iter()
606	        .map(|comp| {
607	            if comp.get_tag().is_some() {
608	                comp
609	            } else {
610	                comp.tag(Some(arg.to_string().into()))
611	            }
612	        })
613	        .collect();
614	
615	    debug!("complete_arg_value: values={values:?}");
616	    values
617	}
618	
619	fn rsplit_delimiter<'s, 'o>(
620	    value: Result<&'s str, &'o OsStr>,
621	    delimiter: Option<char>,
622	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
623	    let delimiter = delimiter?;
624	    let value = value.ok()?;
625	    let pos = value.rfind(delimiter)?;
626	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
627	    Some((Some(prefix), Ok(value)))
628	}
