660	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
661	    debug!(
662	        "complete_subcommand: cmd={:?}, value={:?}",
663	        cmd.get_name(),
664	        value
665	    );
666	
667	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
668	        .into_iter()
669	        .filter(|x| x.get_value().starts_with(value))
670	        .collect();
671	    if cmd.is_allow_external_subcommands_set() {
672	        let external_completer = cmd.get::<SubcommandCandidates>();
673	        if let Some(completer) = external_completer {
674	            scs.extend(complete_value_candidates_str(
675	                value,
676	                completer.value_candidates(),
677	            ));
678	        }
679	    }
680	
681	    scs.sort();
682	    scs.dedup();
683	    scs
684	}
