740	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
741	    candidate
742	        .help(arg.get_help().cloned())
743	        .id(Some(format!("arg::{}", arg.get_id())))
744	        .tag(Some(
745	            arg.get_help_heading()
746	                .unwrap_or("Options")
747	                .to_owned()
748	                .into(),
749	        ))
750	        .display_order(Some(arg.get_display_order()))
751	        .hide(arg.is_hide_set())
