754	/// Get the possible values for completion
755	fn possible_values(
756	    a: &clap::Arg,
757	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
758	    if !a.get_num_args().expect("built").takes_values() {
759	        None
760	    } else {
761	        a.get_value_parser().possible_values()
762	    }
763	}
