785	fn populate_command_candidate(
786	    candidate: CompletionCandidate,
787	    cmd: &clap::Command,
788	    subcommand: &clap::Command,
789	) -> CompletionCandidate {
790	    candidate
791	        .help(subcommand.get_about().cloned())
792	        .id(Some(format!("command::{}", subcommand.get_name())))
793	        .tag(Some(
794	            cmd.get_subcommand_help_heading()
795	                .unwrap_or("Commands")
796	                .to_owned()
797	                .into(),
798	        ))
799	        .display_order(Some(subcommand.get_display_order()))
800	        .hide(subcommand.is_hide_set())
801	}
