803	/// Parse the short flags and find the first `takes_values` option.
804	fn parse_shortflags<'c, 's>(
805	    cmd: &'c clap::Command,
806	    mut short: clap_lex::ShortFlags<'s>,
807	) -> (String, Option<&'c clap::Arg>, clap_lex::ShortFlags<'s>) {
808	    let takes_value_opt;
809	    let mut leading_flags = String::new();
810	    // Find the first takes_values option.
811	    loop {
812	        match short.next_flag() {
813	            Some(Ok(opt)) => {
814	                leading_flags.push(opt);
815	                let opt = cmd.get_arguments().find(|a| {
816	                    let shorts = a.get_short_and_visible_aliases();
817	                    let is_find = shorts.map(|v| {
818	                        let mut iter = v.into_iter();
819	                        let c = iter.find(|c| *c == opt);
820	                        c.is_some()
821	                    });
822	                    is_find.unwrap_or(false)
823	                });
824	                if opt
825	                    .map(|o| o.get_num_args().expect("built").takes_values())
826	                    .unwrap_or(false)
827	                {
828	                    takes_value_opt = opt;
829	                    break;
830	                }
831	            }
832	            Some(Err(_)) | None => {
833	                takes_value_opt = None;
834	                break;
835	            }
836	        }
837	    }
838	
839	    (leading_flags, takes_value_opt, short)
840	}
