842	/// Parse the positional arguments. Return the new state and the new positional index.
843	fn parse_positional<'a>(
844	    cmd: &clap::Command,
845	    pos_index: usize,
846	    is_escaped: bool,
847	    state: ParseState<'a>,
848	) -> (ParseState<'a>, usize) {
849	    let pos_arg = cmd
850	        .get_positionals()
851	        .find(|p| p.get_index() == Some(pos_index));
852	    let num_args = pos_arg
853	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
854	        .unwrap_or(1);
855	
856	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
857	        if num_args > 1 {
858	            (ParseState::Pos((pos_index, 1)), pos_index)
859	        } else {
860	            if is_escaped {
861	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
862	            } else {
863	                (ParseState::ValueDone, pos_index + 1)
864	            }
865	        }
866	    };
867	    match state {
868	        ParseState::ValueDone => {
869	            update_state_with_new_positional(pos_index)
870	        },
871	        ParseState::Pos((prev_pos_index, num_arg)) => {
872	            if prev_pos_index == pos_index {
873	                if num_arg + 1 < num_args {
874	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
875	                } else {
876	                    if is_escaped {
877	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
878	                    } else {
879	                        (ParseState::ValueDone, pos_index + 1)
880	                    }
881	                }
882	            } else {
883	                update_state_with_new_positional(pos_index)
884	            }
885	        }
886	        ParseState::Opt(..) => unreachable!(
887	            "This branch won't be hit,
888	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
889	        ),
890	    }
891	}
892	
893	/// Parse optional flag argument. Return new state
894	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
895	    let range = opt.get_num_args().expect("built");
896	    let max = range.max_values();
897	    if count < max {
898	        ParseState::Opt((opt, count + 1))
899	    } else {
900	        ParseState::ValueDone
901	    }
902	}
903	
904	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
905	    cmd.get_positionals()
906	        .find(|a| a.get_index() == Some(pos_index))
907	        .map(|p| p.is_allow_hyphen_values_set())
908	        .unwrap_or(false)
909	}
910	
911	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
912	    let val = arg.to_value_os();
913	    if val.starts_with("-") {
914	        if let ParseState::Opt((opt, _)) = state {
915	            return opt.is_allow_hyphen_values_set();
916	        }
917	    }
918	
919	    false
920	}
921	
922	/// Whether a committed token looks like an option or the escape token rather
923	/// than a plain value.
924	fn looks_like_option(arg: &clap_lex::ParsedArg<'_>) -> bool {
925	    arg.is_escape()
926	        || arg.to_long().is_some_and(|(flag, _)| flag.is_ok())
927	        || arg
928	            .to_short()
929	            .is_some_and(|short| !short.is_negative_number())
930	}
931	
932	/// Whether the argument may occur more than once on a command line, taking an
933	/// additional value each time.
934	fn can_repeat(arg: &clap::Arg) -> bool {
935	    matches!(
936	        arg.get_action(),
937	        clap::ArgAction::Append | clap::ArgAction::Count
938	    )
939	}
940	
941	/// Resolve the option named by a cursor token, if it is a recognizable long or
942	/// short option.
943	fn cursor_option<'c>(
944	    cmd: &'c clap::Command,
945	    arg: &clap_lex::ParsedArg<'_>,
946	) -> Option<&'c clap::Arg> {
947	    if let Some((flag, _)) = arg.to_long() {
948	        let flag = flag.ok()?;
949	        cmd.get_arguments().find(|a| {
950	            a.get_long_and_visible_aliases()
951	                .map(|longs| longs.into_iter().any(|long| long == flag))
952	                .unwrap_or(false)
953	        })
954	    } else if let Some(short) = arg.to_short() {
955	        let (_, opt, _) = parse_shortflags(cmd, short);
956	        opt
957	    } else {
958	        None
959	    }
960	}
961	
962	/// Validate a value already committed on the command line (not the token under
963	/// the cursor). Unlike the token being completed, a finished value must match
964	/// one of the argument's possible values exactly; an unfinished or illegal
965	/// value invalidates the whole command line and yields no candidates.
966	fn is_valid_value(arg: &clap::Arg, value: &OsStr) -> bool {
967	    let Some(possible) = possible_values(arg) else {
968	        return true;
969	    };
970	    let Some(value) = value.to_str() else {
971	        return false;
972	    };
973	    let possible: Vec<clap::builder::PossibleValue> = possible.collect();
974	    let matches = |part: &str| {
975	        possible
976	            .iter()
977	            .flat_map(|p| p.get_name_and_aliases())
978	            .any(|name| name == part)
979	    };
980	    match arg.get_value_delimiter() {
981	        Some(delimiter) => value.split(delimiter).all(matches),
982	        None => matches(value),
983	    }
984	}
