6	/// Bash completion adapter
7	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
8	pub struct Bash;
9	
10	impl EnvCompleter for Bash {
11	    fn name(&self) -> &'static str {
12	        "bash"
13	    }
14	    fn is(&self, name: &str) -> bool {
15	        name == "bash"
16	    }
17	    fn write_registration(
18	        &self,
19	        var: &str,
20	        name: &str,
21	        bin: &str,
22	        completer: &str,
23	        buf: &mut dyn std::io::Write,
24	    ) -> Result<(), std::io::Error> {
25	        let escaped_name = name.replace('-', "_");
26	
27	        let completer =
28	            shlex::try_quote(completer).unwrap_or(std::borrow::Cow::Borrowed(completer));
29	
30	        let script = r#"
31	_clap_complete_NAME() {
32	    local IFS=$'\013'
33	    local _CLAP_COMPLETE_INDEX=${COMP_CWORD}
34	    local _CLAP_COMPLETE_COMP_TYPE=${COMP_TYPE}
35	    if compopt +o nospace 2> /dev/null; then
36	        local _CLAP_COMPLETE_SPACE=false
37	    else
38	        local _CLAP_COMPLETE_SPACE=true
39	    fi
40	    local words=("${COMP_WORDS[@]}")
41	    if [[ "${BASH_VERSINFO[0]}" -ge 4 ]]; then
42	        words[COMP_CWORD]="$2"
43	    fi
44	    COMPREPLY=( $( \
45	        _CLAP_IFS="$IFS" \
46	        _CLAP_COMPLETE_INDEX="$_CLAP_COMPLETE_INDEX" \
47	        _CLAP_COMPLETE_COMP_TYPE="$_CLAP_COMPLETE_COMP_TYPE" \
48	        _CLAP_COMPLETE_SPACE="$_CLAP_COMPLETE_SPACE" \
49	        VAR="bash" \
50	        "COMPLETER" -- "${words[@]}" \
51	    ) )
52	    if [[ $? != 0 ]]; then
53	        unset COMPREPLY
54	    elif [[ $_CLAP_COMPLETE_SPACE == false ]] && [[ "${COMPREPLY-}" =~ [=/:]$ ]]; then
55	        compopt -o nospace
56	    fi
57	}
58	if [[ "${BASH_VERSINFO[0]}" -eq 4 && "${BASH_VERSINFO[1]}" -ge 4 || "${BASH_VERSINFO[0]}" -gt 4 ]]; then
59	    complete -o nospace -o bashdefault -o nosort -F _clap_complete_NAME BIN
60	else
61	    complete -o nospace -o bashdefault -F _clap_complete_NAME BIN
62	fi
63	"#
64	        .replace("NAME", &escaped_name)
65	        .replace("BIN", bin)
66	        .replace("COMPLETER", &completer)
67	        .replace("VAR", var);
68	
69	        writeln!(buf, "{script}")?;
70	        Ok(())
71	    }
72	    fn write_complete(
73	        &self,
74	        cmd: &mut clap::Command,
75	        args: Vec<OsString>,
76	        current_dir: Option<&std::path::Path>,
77	        buf: &mut dyn std::io::Write,
78	    ) -> Result<(), std::io::Error> {
79	        let index: usize = std::env::var("_CLAP_COMPLETE_INDEX")
80	            .ok()
81	            .and_then(|i| i.parse().ok())
82	            .unwrap_or_default();
83	        let _comp_type: CompType = std::env::var("_CLAP_COMPLETE_COMP_TYPE")
84	            .ok()
85	            .and_then(|i| i.parse().ok())
86	            .unwrap_or_default();
87	        let _space: Option<bool> = std::env::var("_CLAP_COMPLETE_SPACE")
88	            .ok()
89	            .and_then(|i| i.parse().ok());
90	        let ifs: Option<String> = std::env::var("_CLAP_IFS").ok().and_then(|i| i.parse().ok());
91	        let completions = crate::engine::complete(cmd, args, index, current_dir)?;
92	
