32	    /// Create a range
33	    ///
34	    /// # Panics
35	    ///
36	    /// In debug builds, if the range accepts no values. For an exclusive range
37	    /// (`start..end`) that means `end` must be greater than `start`, so both
38	    /// reversed ranges like `10..5` and empty ranges like `5..5` panic.
39	    ///
40	    /// # Examples
41	    ///
42	    /// ```rust
43	    /// # use clap_builder as clap;
44	    /// # use clap::builder::ValueRange;
45	    /// let range = ValueRange::new(5);
46	    /// let range = ValueRange::new(5..10);
47	    /// let range = ValueRange::new(5..=10);
48	    /// let range = ValueRange::new(5..);
49	    /// let range = ValueRange::new(..10);
50	    /// let range = ValueRange::new(..=10);
51	    /// ```
52	    ///
53	    /// While these will panic:
54	    /// ```should_panic
55	    /// # use clap_builder as clap;
56	    /// # use clap::builder::ValueRange;
57	    /// let range = ValueRange::new(10..5);  // Panics! (reversed)
58	    /// ```
59	    /// ```should_panic
60	    /// # use clap_builder as clap;
61	    /// # use clap::builder::ValueRange;
62	    /// let range = ValueRange::new(5..5);  // Panics! (empty)
63	    /// ```
64	    pub fn new(range: impl Into<Self>) -> Self {
65	        range.into()
66	    }
67	
68	    pub(crate) fn raw(start_inclusive: usize, end_inclusive: usize) -> Self {
69	        debug_assert!(start_inclusive <= end_inclusive);
70	        Self {
71	            start_inclusive,
72	            end_inclusive,
73	        }
74	    }
75	
76	    /// Fewest number of values the argument accepts
77	    pub fn min_values(&self) -> usize {
78	        self.start_inclusive
79	    }
80	
81	    /// Most number of values the argument accepts
82	    pub fn max_values(&self) -> usize {
83	        self.end_inclusive
84	    }
85	
86	    /// Report whether the argument takes any values (ie is a flag)
87	    ///
88	    /// # Examples
89	    ///
90	    /// ```rust
91	    /// # use clap_builder as clap;
92	    /// # use clap::builder::ValueRange;
93	    /// let range = ValueRange::new(5);
94	    /// assert!(range.takes_values());
95	    ///
96	    /// let range = ValueRange::new(0);
97	    /// assert!(!range.takes_values());
98	    /// ```
99	    pub fn takes_values(&self) -> bool {
100	        self.end_inclusive != 0
101	    }
102	
103	    pub(crate) fn is_unbounded(&self) -> bool {
104	        self.end_inclusive == usize::MAX
105	    }
106	
