#![cfg(feature = "unstable-dynamic")]

use clap::Command;
use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};

fn spec_command() -> Command {
    Command::new("tool")
        .arg(
            clap::Arg::new("color")
                .long("color")
                .action(clap::ArgAction::Append)
                .num_args(0..=1)
                .value_parser(["auto", "always", "never"]),
        )
        .arg(
            clap::Arg::new("format")
                .long("format")
                .required(true)
                .value_parser(["json", "yaml"]),
        )
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .value_parser(["fast", "safe"]),
        )
        .arg(
            clap::Arg::new("tag")
                .long("tag")
                .action(clap::ArgAction::Append)
                .num_args(1..)
                .add(ArgValueCandidates::new(|| {
                    vec![
                        CompletionCandidate::new("red"),
                        CompletionCandidate::new("blue"),
                    ]
                })),
        )
        .arg(
            clap::Arg::new("template")
                .long("template")
                .add(ArgValueCandidates::new(|| {
                    vec![
                        CompletionCandidate::new("daily"),
                        CompletionCandidate::new("weekly"),
                    ]
                })),
        )
        .arg(
            clap::Arg::new("files")
                .action(clap::ArgAction::Append)
                .add(ArgValueCandidates::new(|| {
                    vec![
                        CompletionCandidate::new("a.txt"),
                        CompletionCandidate::new("b.txt"),
                    ]
                })),
        )
}

fn complete_argv(cmd: &mut Command, argv: &[&str]) -> Vec<String> {
    let arg_index = argv.len() - 1;
    let args = argv.iter().map(std::ffi::OsString::from).collect();
    clap_complete::engine::complete(cmd, args, arg_index, None)
        .unwrap()
        .into_iter()
        .map(|c| c.get_value().to_string_lossy().into_owned())
        .collect()
}

#[test]
fn probe() {
    let cases: &[(&str, &[&str], &[&str])] = &[
        ("color space", &["tool", "--color", ""], &["auto", "always", "never"]),
        ("color eq", &["tool", "--color=au"], &["auto"]),
        ("format space", &["tool", "--format", ""], &["json", "yaml"]),
        ("format eq", &["tool", "--format=ya"], &["yaml"]),
        ("color then format", &["tool", "--color", "--format", ""], &["json", "yaml"]),
        ("color= then format js", &["tool", "--color=", "--format", "js"], &[]),
        ("mode space", &["tool", "--mode", ""], &["fast", "safe"]),
        ("mode eq", &["tool", "--mode=fa"], &["fast"]),
        ("tag space", &["tool", "--tag", ""], &["red", "blue"]),
        ("tag second val", &["tool", "--tag", "red", ""], &["red", "blue"]),
        ("tag eq", &["tool", "--tag=r"], &["red"]),
        ("template space", &["tool", "--template", ""], &["daily", "weekly"]),
        ("template eq", &["tool", "--template=w"], &["weekly"]),
        ("dashdash", &["tool", "--", ""], &["a.txt", "b.txt"]),
        ("repeat color", &["tool", "--color", "auto", "--color", ""], &["auto", "always", "never"]),
        ("repeat color eq", &["tool", "--color=auto", "--color="], &["auto", "always", "never"]),
        ("repeat tag", &["tool", "--tag", "red", "--tag", ""], &["red", "blue"]),
        ("missing required", &["tool", "--format", "--color", "au"], &[]),
        ("dup single", &["tool", "--mode", "fast", "--mode", ""], &[]),
        ("dup single eq", &["tool", "--mode=fast", "--mode=f"], &[]),
        ("unfinished eq committed", &["tool", "--color=au", ""], &[]),
        ("unknown opt", &["tool", "--bogus", ""], &[]),
        ("illegal prefix committed", &["tool", "--color=red", "--format", ""], &[]),
        ("opt as value", &["tool", "--format", "--mode"], &[]),
        ("dashdash option-like", &["tool", "--", "--color"], &[]),
        ("delim eq comma", &["delimiter", "--delimiter=comma,"], &[]),
    ];
    for (name, argv, expected) in cases {
        let mut cmd = if *name == "delim eq comma" {
            Command::new("delimiter")
                .arg(
                    clap::Arg::new("delimiter")
                        .long("delimiter")
                        .short('D')
                        .value_parser(["comma", "space", "tab"])
                        .value_delimiter(','),
                )
                .arg(
                    clap::Arg::new("pos")
                        .value_parser(["a_pos", "b_pos", "c_pos"])
                        .value_delimiter(','),
                )
        } else {
            spec_command()
        };
        let actual = complete_argv(&mut cmd, argv);
        let status = if actual.iter().map(String::as_str).collect::<Vec<_>>() == *expected {
            "OK  "
        } else {
            "FAIL"
        };
        println!("{status} {name}: got={actual:?} want={expected:?}");
    }
}

